// Generated by scripts/bundle-rules.mjs from rules/*.yaml. Do not edit.
export const bundledRuleSources: Record<string, string> = {
  "container.yaml": "# Starter rules for containers in a Pod or Deployment.\nid: image-latest-tag\ntitle: Image has no fixed version\nseverity: warning\nkinds: ['*']\nscope: [container, initContainer]\nwhen:\n  any:\n    - matches: { image: '^(?!.*@).*:latest$' }\n    - matches: { image: '^(?!.*@)([^/]*/)*[^/:]+$' }\nreport: image\nmessage: 'Container \"{container}\" uses image \"{value}\", which has no fixed version.'\nwhy: The \"latest\" tag (or no tag) points at whatever was pushed most recently. The same manifest can run different code tomorrow, and you cannot roll back to a known version.\nfix: Use a specific version tag such as nginx:1.27, or an image digest (nginx@sha256:...).\n---\nid: missing-memory-limit\ntitle: Container has no memory limit\nseverity: warning\nkinds: ['*']\nscope: container\nwhen:\n  missing: resources.limits.memory\nreport: resources\nmessage: 'Container \"{container}\" has no memory limit.'\nwhy: A container without a memory limit can use all the memory on its node, which can starve or crash other workloads.\nfix: 'Add resources.limits.memory, for example: limits: { memory: 256Mi }.'\n---\nid: missing-resource-requests\ntitle: Container has no CPU or memory request\nseverity: warning\nkinds: ['*']\nscope: container\nwhen:\n  any:\n    - missing: resources.requests.cpu\n    - missing: resources.requests.memory\nreport: resources\nmessage: 'Container \"{container}\" does not request both CPU and memory.'\nwhy: The scheduler uses requests to decide which node has room for the Pod. Without them it guesses, and Pods can be packed onto nodes that are too small.\nfix: 'Add resources.requests.cpu and resources.requests.memory, for example: requests: { cpu: 100m, memory: 128Mi }.'\n---\nid: missing-readiness-probe\ntitle: Container has no readiness probe\nseverity: warning\nkinds: ['*']\nscope: container\nwhen:\n  missing: readinessProbe\nmessage: 'Container \"{container}\" has no readiness probe.'\nwhy: Without a readiness probe Kubernetes sends traffic to the Pod as soon as the container starts, even if the app is not ready yet. Rolling updates can then cause failed requests.\nfix: Add a readinessProbe, for example an httpGet on a health endpoint of your app.\n---\nid: missing-liveness-probe\ntitle: Container has no liveness probe\nseverity: info\nkinds: ['*']\nscope: container\nwhen:\n  missing: livenessProbe\nmessage: 'Container \"{container}\" has no liveness probe.'\nwhy: Without a liveness probe Kubernetes only restarts the container when the process exits. A container that is stuck but still running is never restarted.\nfix: Add a livenessProbe that checks the app is still responding. Keep it simple so it does not fail under load.\n---\nid: privileged-container\ntitle: Container runs in privileged mode\nseverity: error\nkinds: ['*']\nscope: [container, initContainer]\nwhen:\n  equals: { securityContext.privileged: true }\nreport: securityContext.privileged\nmessage: 'Container \"{container}\" runs in privileged mode.'\nwhy: A privileged container has almost the same access as a process running directly on the node. If it is compromised, the whole node is at risk.\nfix: Remove privileged, or replace it with the specific capabilities the container needs under securityContext.capabilities.add.\n---\nid: run-as-root-user\ntitle: Container is set to run as root\nseverity: error\nkinds: ['*']\nscope: [container, initContainer]\nwhen:\n  any:\n    - equals: { securityContext.runAsUser: 0 }\n    - all:\n        - equals: { $pod.securityContext.runAsUser: 0 }\n        - missing: securityContext.runAsUser\nreport: securityContext.runAsUser\nmessage: 'Container \"{container}\" is explicitly set to run as root (user 0).'\nwhy: Root inside a container makes it much easier to attack the node if the container is compromised.\nfix: Set runAsUser to a non-zero ID such as 1000 and set runAsNonRoot to true.\n---\nid: may-run-as-root\ntitle: Container is not prevented from running as root\nseverity: warning\nkinds: ['*']\nscope: [container, initContainer]\nwhen:\n  all:\n    - not: { equals: { securityContext.runAsNonRoot: true } }\n    - not: { equals: { $pod.securityContext.runAsNonRoot: true } }\n    - not: { matches: { securityContext.runAsUser: '^[1-9][0-9]*$' } }\n    - not: { matches: { $pod.securityContext.runAsUser: '^[1-9][0-9]*$' } }\nreport: securityContext\nmessage: 'Container \"{container}\" is not prevented from running as root.'\nwhy: Many images run as root by default. Unless you say otherwise, Kubernetes lets them.\nfix: Set securityContext.runAsNonRoot to true (on the container or on the Pod), or set runAsUser to a non-zero ID.\n---\nid: allow-privilege-escalation\ntitle: Container may gain extra privileges\nseverity: warning\nkinds: ['*']\nscope: [container, initContainer]\nwhen:\n  not: { equals: { securityContext.allowPrivilegeEscalation: false } }\nreport: securityContext.allowPrivilegeEscalation\nmessage: 'Container \"{container}\" does not disable privilege escalation.'\nwhy: Privilege escalation lets a process gain more rights than its parent, for example through setuid programs. It is on by default.\nfix: Set securityContext.allowPrivilegeEscalation to false.\n---\nid: writable-root-filesystem\ntitle: Container can write to its own filesystem\nseverity: info\nkinds: ['*']\nscope: [container, initContainer]\nwhen:\n  not: { equals: { securityContext.readOnlyRootFilesystem: true } }\nreport: securityContext.readOnlyRootFilesystem\nmessage: 'Container \"{container}\" has a writable root filesystem.'\nwhy: If an attacker gets into the container, a read-only filesystem stops them from dropping tools or changing the application files.\nfix: Set securityContext.readOnlyRootFilesystem to true, and mount an emptyDir volume for any directory the app must write to.\n---\nid: capabilities-not-dropped\ntitle: Container keeps default Linux capabilities\nseverity: info\nkinds: ['*']\nscope: [container, initContainer]\nwhen:\n  not: { contains: { securityContext.capabilities.drop: ALL } }\nreport: securityContext.capabilities\nmessage: 'Container \"{container}\" does not drop all Linux capabilities.'\nwhy: Containers start with a set of Linux capabilities most apps never use. Each one is extra attack surface.\nfix: 'Set securityContext.capabilities.drop to [ALL] and add back only what the app needs.'\n",
  "deployment.yaml": "# Starter rules for Deployments.\nid: single-replica\ntitle: Deployment runs a single Pod\nseverity: info\nkinds: [Deployment]\nwhen:\n  any:\n    - missing: spec.replicas\n    - equals: { spec.replicas: 1 }\nreport: spec.replicas\nmessage: 'Deployment \"{name}\" runs only one replica.'\nwhy: With one Pod, any restart, node failure or rolling update means downtime.\nfix: Set spec.replicas to 2 or more for anything that should stay available.\n",
  "pod.yaml": "# Starter rules for the Pod spec (a Pod, or a Deployment's Pod template).\nid: host-namespaces\ntitle: Pod shares the node's network, process or IPC space\nseverity: warning\nkinds: ['*']\nscope: pod\nwhen:\n  any:\n    - equals: { hostNetwork: true }\n    - equals: { hostPID: true }\n    - equals: { hostIPC: true }\nreport: [hostNetwork, hostPID, hostIPC]\nmessage: \"The Pod shares the node's network, process or IPC namespace.\"\nwhy: Sharing these namespaces removes the isolation between the Pod and the node. The Pod can see node traffic or other processes.\nfix: Remove hostNetwork, hostPID and hostIPC unless this Pod is a node-level agent that really needs them.\n---\nid: hostpath-volume\ntitle: Pod mounts a directory from the node\nseverity: warning\nkinds: ['*']\nscope: pod\nwhen:\n  present: volumes[].hostPath\nreport: volumes[].hostPath\nmessage: \"The Pod mounts a directory from the node's filesystem.\"\nwhy: A hostPath volume gives the Pod access to files on the node. A compromised Pod can read or change them, and the Pod becomes tied to specific nodes.\nfix: Use an emptyDir, a ConfigMap, a Secret or a PersistentVolumeClaim instead.\n",
  "service.yaml": "# Starter rules for Services.\nid: nodeport-service\ntitle: Service is exposed on every node\nseverity: info\nkinds: [Service]\nwhen:\n  equals: { spec.type: NodePort }\nreport: spec.type\nmessage: 'Service \"{name}\" opens a port on every node in the cluster.'\nwhy: NodePort exposes the Service on a high port of every node. It is easy to expose more than you meant to, and node IPs may be reachable from outside.\nfix: Use ClusterIP with an Ingress or Gateway, or a LoadBalancer with source ranges.\n---\nid: loadbalancer-open-to-world\ntitle: Load balancer is open to all addresses\nseverity: warning\nkinds: [Service]\nwhen:\n  all:\n    - equals: { spec.type: LoadBalancer }\n    - missing: spec.loadBalancerSourceRanges\nreport: spec.type\nmessage: 'Service \"{name}\" creates a load balancer that accepts traffic from any address.'\nwhy: By default a LoadBalancer Service is reachable from the whole internet (on most clouds).\nfix: Set spec.loadBalancerSourceRanges to the IP ranges that should have access.\n",
};
